module bible/types v1.0.0;

import "io/stdout" take Stdout;

role Shape {
    area() is rat;
}

object Square does Shape {
    has side is int;
    Square(side is int) { self.side = side; }
    area() is rat { (side * side).rat(); }
}

object Triangle does Shape {
    has base, height is int;
    Triangle(base is int, height is int) { self.base = base; self.height = height; }
    area() is rat { base * height / 2; }
}

main() is int {
    let out = Stdout();
    let count = 3;                                   // inferred: int
    let ratio is rat = 1 / count;                    // declared: rat
    let names is @string = ["square", "triangle"];   // an array of strings
    let sides is %string:int = ["square": 4, "triangle": 3];
    let shapes is @Shape = [Square(3), Triangle(5, 3)];
    let total = shapes.reduce(0.rat()) -> sum, shape { sum + shape.area(); };
    out.writeln("ratio " + ratio.string());
    out.writeln(names.join(", ") + " have " + (sides["square"] + sides["triangle"]).string() + " sides");
    out.writeln("total area " + total.string());
    0;
}

module app v1.0.0;

object NewtonSeconds {
    has amount is rat;
    NewtonSeconds(:amount);
    plus(other is NewtonSeconds) is NewtonSeconds { NewtonSeconds(amount: amount + other.size()); }
    size() is rat { amount; }
}

object PoundSeconds {
    has amount is rat;
    PoundSeconds(:amount);
}

main() is int {
    let start = NewtonSeconds(amount: 0.rat());
    // Same shape, different meaning: the compiler does not accept one for the other.
    let total = start.plus(PoundSeconds(amount: 12.rat()));
    0;
}

module app v1.0.0;

import "io/stdout" take Stdout;

// Impulse in the units the navigation software expects.
object NewtonSeconds {
    has amount is rat;
    NewtonSeconds(:amount);
    plus(other is NewtonSeconds) is NewtonSeconds { NewtonSeconds(amount: amount + other.size()); }
    size() is rat { amount; }
    shown() is string { amount.float().string() + " N*s"; }
}

// Impulse in the units a thruster table was written in.
object PoundSeconds {
    has amount is rat;
    PoundSeconds(:amount);
    // One pound-force is exactly 0.45359237 kg * 9.80665 m/s^2 = 4.4482216152605 N.
    newton_seconds() is NewtonSeconds {
        NewtonSeconds(amount: amount * 44482216152605.rat() / 10000000000000.rat());
    }
}

main() is int {
    let out = Stdout();
    let burns = [PoundSeconds(amount: 12.rat()), PoundSeconds(amount: 7.rat() / 2.rat())];
    // The conversion is a call, written where the two kinds of number meet.
    let total = burns.map() -> burn { burn.newton_seconds(); }
        .reduce(NewtonSeconds(amount: 0.rat())) -> sum, n { sum.plus(n); };
    out.writeln(total.shown());
    0;
}

module app v1.0.0;

import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    // Ten dimes as floats and as rats.
    let floats = (1..=10).reduce(0.0) -> sum, n { sum + 0.1; };
    let rats = (1..=10).reduce(0.rat()) -> sum, n { sum + 1.rat() / 10.rat(); };
    out.writeln(floats.string() + " " + (floats == 1.0).string());
    out.writeln(rats.string() + " " + (rats == 1.rat()).string());
    // A float comparison needs a tolerance; an exact one does not.
    out.writeln(((floats - 1.0).abs() < 0.000000001).string());
    // Monthly interest of 1/12 percent on 1000, twelve times, exactly.
    let balance = (1..=12).reduce(1000.rat()) -> total, month { total + total / 1200.rat(); };
    out.writeln(balance.float().string());
    // Integers never overflow; they grow.
    out.writeln((2).pow(70).string());
    0;
}

module bible/exact v1.0.0;

import "io/stdout" take Stdout;

object Factorial {
    Factorial() {}
    of(n is int) is int {
        if n <= 1 { 1; } else { n * self.of(n - 1); }
    }
}

main() is int {
    let out = Stdout();
    let largest = 9223372036854775807;                 // 2^63 - 1
    out.writeln("2^63 - 1 + 1 = " + (largest + 1).string());
    out.writeln("30! = " + Factorial().of(30).string());
    out.writeln("1/3 + 2/3 = " + (1 / 3 + 2 / 3).string());
    out.writeln("1/10 + 2/10 = " + (1 / 10 + 2 / 10).string());
    out.writeln("0.1 + 0.2 = " + (0.1 + 0.2).string());
    out.writeln("-7 % 3 = " + (-7 % 3).string());
    out.writeln("int(-3.9) = " + int(-3.9).string());
    out.writeln("0.125 as rat = " + 0.125.rat().string());
    out.writeln("1/3 as float = " + (1 / 3).float().string());
    0;
}

module bible/growth v1.0.0;

// Exact numbers grow. Harmonic numbers as rats and as floats, and a year of
// daily interest kept exact or rounded to cents every day.
import "io/stdout" take Stdout;

object Harmonic {
    Harmonic() {}

    exact(n is int) is rat {
        (1..=n).reduce(0.rat()) -> sum, k { sum + 1 / k; };
    }

    approximate(n is int) is float {
        (1..=n).reduce(0.0) -> sum, k { sum + 1.0 / k.float(); };
    }
}

object Deposit {
    has rate is rat;
    Deposit(:rate);

    // One day of interest, kept exact.
    grown(balance is rat) is rat {
        balance + balance * rate / 365.rat();
    }

    // The same day, rounded half up to a cent, as a bank books it.
    booked(balance is rat) is rat {
        int(self.grown(balance) * 100.rat() + 1 / 2).rat() / 100.rat();
    }
}

main() is int {
    let out = Stdout();
    let harmonic = Harmonic();
    out.writeln("H(10) = " + harmonic.exact(10).string());
    for [10, 20, 40, 80, 160] -> n {
        let exact = harmonic.exact(n);
        let error = (exact.float() - harmonic.approximate(n)).abs();
        out.writeln("H(" + n.string() + "): " + exact.string().length().string() + " characters, float off by "
            + error.string());
    }
    let deposit = Deposit(rate: 5 / 100);
    let exact = (1..=365).reduce(1000.rat()) -> balance, day { deposit.grown(balance); };
    let booked = (1..=365).reduce(1000.rat()) -> balance, day { deposit.booked(balance); };
    out.writeln("exact after a year: " + exact.string().length().string() + " characters, about "
        + exact.float().string());
    out.writeln("booked after a year: " + booked.string().length().string() + " characters, "
        + booked.float().string());
    out.writeln("difference in cents: " + ((exact - booked) * 100.rat()).float().string());
    0;
}

module bible/integers v1.0.0;

import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    // Division of two ints is exact: a rat, not a truncated int.
    let half = 7 / 2;
    out.writeln(half.string() + ": numerator " + half.numerator().string() + ", denominator " + half.denominator().string());
    // Truncation toward zero is written, and so is the remainder.
    out.writeln(int(7 / 2).string() + " " + int(-7 / 2).string());
    out.writeln((7 % 3).string() + " " + (-7 % 3).string() + " " + (7 % -3).string());
    // Powers stay exact, past any machine word.
    out.writeln((2).pow(64).string());
    out.writeln(((2).pow(64) - 1).string());
    // Bit operations work on the 64-bit two's complement view of an int.
    out.writeln((12 & 10).string() + " " + (12 | 10).string() + " " + (12 ^ 10).string() + " " + (~5).string());
    out.writeln((1 << 62).string() + " " + (1 << 63).string());
    out.writeln((-8 >> 1).string() + " " + (-1 >>> 60).string());
    out.writeln(255.bit_count().string() + " " + 1.leading_zeros().string() + " " + 8.trailing_zeros().string());
    0;
}

module bible/kahan v1.0.0;

// Floating point in practice: a long sum, kept naively, with Kahan's
// compensation and exactly; and a quadratic whose small root cancels.
import "io/stdout" take Stdout;

// Kahan's compensated sum: `lost` keeps the low-order part that each
// addition rounds away, and the next addition puts it back.
object Compensated {
    has sum is float;
    has lost is float;
    Compensated(:sum, :lost);

    added(x is float) is Compensated {
        let y = x - lost;
        let t = sum + y;
        Compensated(sum: t, lost: (t - sum) - y);
    }

    value() is float { sum; }
}

// The roots of x² + b·x + c with b < 0.
object Quadratic {
    has b is float;
    has c is float;
    Quadratic(:b, :c);

    // The textbook formula for the small root subtracts two nearly equal numbers.
    naive() is float {
        (-b - (b * b - 4.0 * c).sqrt()) / 2.0;
    }

    // The large root has no cancellation; the small one is c divided by it.
    stable() is float {
        let large = (-b + (b * b - 4.0 * c).sqrt()) / 2.0;
        c / large;
    }
}

main() is int {
    let out = Stdout();
    let naive = (1..=100000).reduce(0.0) -> sum, k { sum + 0.1; };
    let compensated = (1..=100000).reduce(Compensated(sum: 0.0, lost: 0.0)) -> sum, k { sum.added(0.1); };
    let exact = (1..=100000).reduce(0.rat()) -> sum, k { sum + 1 / 10; };
    out.writeln("naive:       " + naive.string());
    out.writeln("compensated: " + compensated.value().string());
    out.writeln("exact:       " + exact.string());
    out.writeln("1 + 1e-15 - 1 = " + ((1.0 + 0.000000000000001) - 1.0).string());
    let roots = Quadratic(b: -100000000.0, c: 1.0);
    out.writeln("small root, naive:  " + roots.naive().string());
    out.writeln("small root, stable: " + roots.stable().string());
    0;
}

module bible/money v1.0.0;

import "io/stdout" take Stdout;

// Split a bill of 100.00 between three people, exactly.
object Bill {
    has cents is int;
    Bill(cents is int) { self.cents = cents; }

    // Each share is a rational number of cents; nothing is lost yet.
    share(people is int) is rat { cents / people; }

    // Rounding is a decision: everyone pays the truncated share and the
    // first person pays what is left over.
    shares(people is int) is @int {
        let each = int(self.share(people));
        let rest = cents - each * people;
        (0..people).map() -> index { if index == 0 { each + rest; } else { each; } };
    }
}

main() is int {
    let out = Stdout();
    let bill = Bill(10000);
    out.writeln("exact share: " + bill.share(3).string() + " cents");
    let parts = bill.shares(3);
    out.writeln("paid: " + parts.map() -> part { part.string(); }.join(" + ")
        + " = " + parts.reduce(0) -> sum, part { sum + part; }.string());
    0;
}

module bible/parse v1.0.0;

import "io/stdout" take Stdout;
import "strings/parse" take Number, InvalidInteger, InvalidRational;

// Reads a quantity typed by a person, and says why it is not one.
object Quantity {
    has text is string;

    Quantity(:text);

    described() is string {
        try {
            text + " -> " + Number(text).int().string();
        }
        catch InvalidInteger.source(source) {
            text + " -> not an integer: '" + source + "'";
        };
    }
}

main() is int {
    let out = Stdout();
    out.writeln(Number("42").int().string());
    out.writeln(Number("ff").int(16).string() + " " + Number("0x2A").int(0).string() + " " + Number("101").int(2).string());
    out.writeln(Number("6/8").rat().string() + " " + Number("-42.5").float().string());
    out.writeln(Number("12345678901234567890").int().string());
    for ["17", " 17", "+17", "1_000", "-0"] -> text {
        out.writeln(Quantity(text: text).described());
    }
