module bible/crypto v1.0.0;

// Passwords are stored as Argon2id hashes and checked in constant time; a
// message is signed with HMAC; data is sealed with AES-GCM, and a changed
// byte is refused, not decrypted into something else. Keys are secrets.
import "crypto/password" take PasswordHash, PasswordCheck, Argon2Policy;
import "crypto/hmac" take Hmac, HmacHash;
import "crypto/aes_gcm" take AesGcm;
import "crypto/nonce" take SystemEntropy, RandomNonce;
import "crypto/secret" take SecretBytes;
import "crypto/error" take AuthenticationFailed;
import "encoding/utf" take Utf8Encoded, Utf8Decoded;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let stored = PasswordHash(SecretBytes(Utf8Encoded("correct horse").bytes()), Argon2Policy(),
        SystemEntropy()).string();
    out.writeln("stored as " + stored.slice(0, 10) + "...");
    for ["correct horse", "wrong horse"] -> attempt {
        let check = PasswordCheck(stored, SecretBytes(Utf8Encoded(attempt).bytes()));
        out.writeln(attempt + ": " + check.matches().string());
    }
    let key = SecretBytes(Utf8Encoded("a key of thirty-two bytes, exact").bytes());
    defer key.close();
    let tag = Hmac(HmacHash.sha256, key, "pay 10 to ann").bytes();
    out.writeln("signed: " + Hmac(HmacHash.sha256, key, "pay 10 to ann").matches(tag).string()
        + ", altered: " + Hmac(HmacHash.sha256, key, "pay 99 to ann").matches(tag).string());
    let cipher = AesGcm(key);
    let nonce = RandomNonce(SystemEntropy(), cipher.nonce_size()).bytes();
    let sealed = cipher.sealed(nonce, [], Utf8Encoded("meet at noon").bytes());
    out.writeln("opened: " + Utf8Decoded(cipher.opened(nonce, [], sealed)).string());
    let changed = sealed.replaced(0, (sealed[0].int() ^ 1).byte());
    out.writeln(try { Utf8Decoded(cipher.opened(nonce, [], changed)).string(); }
        catch e is AuthenticationFailed { "changed in transit: refused"; });
    0;
}

module bible/csv v1.0.0;

// CSV with a header: a record is read by column name, and rows are printed
// back with the quoting the format needs. The dialect (separator, quote,
// line end) is a value; the default ends lines with CRLF, this one with LF.
import "csv" take CsvDialect, CsvRecords, CsvString;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let lines = CsvDialect(",", "\"", "\n");
    let orders = CsvRecords("item,qty,note\ntea,2,\"green, loose\"\ncake,1,\n", lines);
    let total = orders.reduce(0) -> sum, record { sum + record.int("qty"); };
    for orders -> record {
        out.writeln(record.text("item") + " x" + record.int("qty").string() + " [" + record.text("note") + "]");
    }
    out.writeln("total " + total.string());
    let rows is @@string = [["item", "note"], ["tea", "green, loose"], ["quote", "say \"hi\""]];
    out.write(CsvString(rows, lines).string());
    0;
}

module bible/ids v1.0.0;

// Identifiers and media types: a UUID is read, made from a name, or drawn
// from an explicit source of randomness; a media type is read into parts,
// and a file name is mapped to one by a table the program chooses.
import "uuid/value" take UuidText;
import "uuid/generation" take Uuid5, Uuid4s;
import "random/source" take SecureRandom;
import "mime/media_type" take MediaType;
import "mime/types" take StandardMediaTypes;
import "fs/path" take Path;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let given = UuidText(origin: "550E8400-E29B-41D4-A716-446655440000");
    out.writeln(given.string() + ", version " + given.version().string());
    let dns = UuidText(origin: "6ba7b810-9dad-11d1-80b4-00c04fd430c8");
    out.writeln("stable: " + Uuid5(namespace: dns, name: "example.com").string());
    out.writeln("drawn: version " + Uuid4s(random: SecureRandom()).sample().version().string());
    let page = MediaType("text/html; charset=UTF-8");
    out.writeln(page::Type::type + " / " + page::Type::subtype + ", charset " + page.parameters().first("charset"));
    let types = StandardMediaTypes();
    out.writeln("report.pdf is " + types.type(Path("report.pdf")).string());
    0;
}

module bible/json_reference v1.0.0;

import "io/stdout" take Stdout;
import "json" take Json, JsonField, ParsedJson, JsonError;

// An order arrives as text, is read without casts, and a reply is built and
// written by the runtime in one call.
object Line {
    has sku is string;
    has qty is int;
    Line(:sku, :qty);

    string() is string {
        sku + " x" + qty.string();
    }
}

main() is int {
    let out = Stdout();
    let order = ParsedJson("{\"id\": 4711, \"customer\": {\"name\": \"Ada\"}, \"items\": [{\"sku\": \"tea\", \"qty\": 2}, {\"sku\": \"cake\", \"qty\": 1}]}").root();
    out.writeln("order ", order.int("id"), " for ", order.get("customer").text("name"));
    out.writeln("note: ", order.maybe("note").text() else "none");
    let lines = order.list("items").map() -> item { Line(sku: item.text("sku"), qty: item.int("qty")); };
    for lines -> line {
        out.writeln("  ", line.string());
    }

    let reply = Json(JsonField("id", 4711), JsonField("state", "accepted"), JsonField("lines", lines.size()));
    out.writeln(reply.string());

    let refused = try {
        order.text("id");
    }
    catch JsonError.wrong_kind(pointer, expected, actual) {
        "wrong kind at " + pointer;
    };
    out.writeln(refused);
    0;
}

module bible/locale v1.0.0;

// What a user reads depends on their language: plural forms come from the
// locale's rules, lists are joined the way the language joins them, dates
// are written in its words.
import "locale/tag" take Locale;
import "i18n/plural" take PluralNumber, PluralCategory;
import "i18n/catalog" take MessageKey, MessageCatalog, PluralMessage, PluralForm;
import "locale/list" take LocalizedList, ListKind, ListStyle;
import "locale/date_time" take LocalizedDate, DateStyle;
import "time/date" take Date;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let unread = MessageKey(context: "", identity: "unread");
    let russian = MessageCatalog(locale: Locale("ru"), entries: [
        PluralMessage(key: unread, forms: [
            PluralForm(category: PluralCategory.one, text: "непрочитанное письмо"),
            PluralForm(category: PluralCategory.few, text: "непрочитанных письма"),
            PluralForm(category: PluralCategory.many, text: "непрочитанных писем"),
            PluralForm(category: PluralCategory.other, text: "непрочитанного письма")
        ])
    ]);
    for ["1", "3", "5", "21", "1.5"] -> count {
        out.writeln(count + " " + russian.plural(unread, PluralNumber(count)));
    }
    for ["en", "ru", "ja"] -> tag {
        out.writeln(LocalizedList(values: ["tea", "milk", "bread"], locale: Locale(tag),
            kind: ListKind.conjunction, style: ListStyle.long).string());
    }
    let day = Date(year: 2026, month: 11, day: 17);
    for ["en", "fr", "ru"] -> tag {
        out.writeln(LocalizedDate(origin: day, locale: Locale(tag), style: DateStyle.long).string());
    }
    0;
}

module bible/net v1.0.0;

// The network's formats without the network: a mail message read from its
// wire form, addresses tested against a network, and the registrable part
// of a host name from the public suffix list.
import "mail/message" take ParsedMail;
import "net/ip" take IpAddress, IpNetwork, IpProperty;
import "net/endpoint" take HostName;
import "net/public_suffix" take PublicSuffixList;
import "encoding/utf" take Utf8Encoded;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let wire = Utf8Encoded("From: Ada <ada@example.test>\r\nTo: grace@example.test\r\n" +
        "Subject: Lunch on Thursday?\r\nContent-Type: text/plain; charset=utf-8\r\n\r\n" +
        "Shall we try the new place?\r\n").bytes();
    let mail = ParsedMail(wire).message();
    out.writeln(mail.headers().first("From") + " asks: " + mail.headers().first("Subject"));
    let office = IpNetwork(IpAddress("10.0.0.0"), 8);
    for ["10.1.2.3", "192.168.1.10", "8.8.8.8"] -> text {
        let address = IpAddress(text);
        out.writeln(text + ": in the office " + office.membership(address).string()
            + ", private " + address.properties().membership(IpProperty.private_network).string());
    }
    let suffixes = PublicSuffixList();
    for ["www.example.co.uk", "ada.github.io", "пример.рф"] -> host {
        out.writeln(host + " belongs to " + suffixes.registrable(HostName(host)).unicode());
    }
    out.writeln("on the wire: " + HostName("пример.рф").ascii());
    0;
}

module bible/numbers v1.0.0;

// Exact money with Decimal and a rounding the program names, shown to people
// through a locale; a sample's summary statistics and a fitted line; and a
// float sum that keeps the small terms.
import "math/decimal" take Decimal;
import "math/rounding" take Rounding;
import "math/aggregate" take Numbers;
import "statistics" take Sample, Pairs;
import "locale/tag" take Locale;
import "locale/number" take NumberFormat, NumberNotation, NumberGrouping, NumberSign, NumberPrecision;
import "locale/currency" take Currency, CurrencyFormat, CurrencyDisplay, LocalizedCurrency;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let total = Decimal("19.99").times(Decimal(3)).plus(Decimal("0.10"));
    out.writeln("stored " + total.string() + ", split in 7: "
        + total.divided(by: Decimal(7), scale: 2, rounding: Rounding.half_even).string());
    out.writeln("2.5 to even: " + Decimal("2.5").rounded(scale: 0, rounding: Rounding.half_even).string()
        + ", away from zero: " + Decimal("2.5").rounded(scale: 0, rounding: Rounding.away_from_zero).string());
    let digits = NumberFormat(notation: NumberNotation.standard, grouping: NumberGrouping.automatic,
        sign: NumberSign.automatic, precision: NumberPrecision(minimum_integer: 1, minimum_fraction: 2,
            maximum_fraction: 2, rounding: Rounding.half_even));
    let money = CurrencyFormat(numbers: digits, display: CurrencyDisplay.symbol, accounting: false,
        currency_digits: true);
    for ["en", "de"] -> tag {
        out.writeln(tag + ": " + LocalizedCurrency(amount: total.times(Decimal(1000)), currency: Currency("EUR"),
            locale: Locale(tag), format: money).string());
    }
    let times = Sample(values: [12.0, 15.0, 11.0, 30.0, 14.0, 14.0]);
    out.writeln("mean " + times.mean().string() + ", median " + times.median().string()
        + ", deviation " + ((times.deviation() * 100.0).round() / 100.0).string());
    let fit = Pairs(left: [1.0, 2.0, 3.0, 4.0], right: [2.1, 3.9, 6.2, 7.8]).line();
    out.writeln("predicted at 5: " + ((fit.prediction(at: 5.0) * 100.0).round() / 100.0).string());
    let terms = [1.0e16, 1.0, -1.0e16];
    out.writeln("sum " + Numbers(values: terms).sum().string()
        + ", accurate " + Numbers(values: terms).accurate_sum().string());
    0;
}

module bible/packing v1.0.0;

// Compression with a limit on what comes back out, and a ZIP archive written
// into memory and read again; an entry's path cannot climb out of the archive.
import "compression/gzip" take GzipCompressed, GzipDecompressed;
import "compression/state" take CompressionLimitExceeded;
import "archive/zip" take ZipWriting, ZipArchive;
import "archive/path" take UnsafeArchivePath;
import "io/buffer" take ByteBuffer;
import "encoding/utf" take Utf8Encoded, Utf8Decoded;
import "io/stdout" take Stdout;

async main() is int {
    let out = Stdout();
    let text = Utf8Encoded("tea ".repeat(250)).bytes();
    let packed = GzipCompressed(text).bytes();
    out.writeln(text.size().string() + " bytes packed into " + packed.size().string());
    out.writeln("back: " + (GzipDecompressed(origin: packed, limit: 4096).bytes() == text).string());
    out.writeln(try { GzipDecompressed(origin: packed, limit: 100).bytes().size().string(); }
        catch e is CompressionLimitExceeded { "over the limit: refused"; });
    let buffer = ByteBuffer();
    let zip = ZipWriting(destination: buffer.writing());
    zip.add(name: "notes/a.txt", bytes: Utf8Encoded("first").bytes());
    zip.add(name: "notes/b.txt", bytes: text);
    out.writeln(try { zip.add(name: "../escape.txt", bytes: []); "added"; }
        catch e is UnsafeArchivePath { "../escape.txt: refused"; });
    zip.close();
    for ZipArchive(buffer.content().bytes()).entries() -> entry {
        out.writeln(entry.name() + ": " + (await entry.bytes(limit: 4096)).size().string() + " bytes");
    }
    0;
}

module bible/toml v1.0.0;

// A configuration file read the way json is read: by name, with the type
// asked for at the point of use, and absence decided where it is allowed.
import "toml/parse" take ParsedToml, InvalidToml;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let config = ParsedToml("title = \"shop\"\n" +
        "[server]\nhost = \"0.0.0.0\"\nport = 8080\n" +
        "[[mirror]]\nurl = \"https://a.example\"\nweight = 3\n" +
        "[[mirror]]\nurl = \"https://b.example\"\n").root();
    let server = config.get("server");
    out.writeln(config.text("title") + " on " + server.text("host") + ":" + server.int("port").string());
    out.writeln("debug: " + (config.maybe("debug").boolean() else false).string());
    for config.tables("mirror") -> mirror {
        out.writeln(mirror.text("url") + " weight " + (mirror.maybe("weight").int() else 1).string());
    }
    out.writeln(try { ParsedToml("port = 80\nport = 81\n").root().int("port").string(); }
        catch e is InvalidToml { "refused: " + e.text(); });
    0;
}

module bible/url v1.0.0;

// A URL taken apart through its cap, its query read by name, and a relative
// reference resolved against it (RFC 3986).
import "url/value" take ParsedUrl;
import "url/query" take ParsedQuery;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let page = ParsedUrl("https://ada@example.org:8443/docs/guide/intro?lang=en&v=2#start").parts();
    out.writeln(page::Parts::scheme + " " + (page::Parts::host else "-") + " " + (page::Parts::port else 443).string());
    out.writeln(page::Parts::path);
    let query = ParsedQuery(page::Parts::query else "").parameters();
    out.writeln("lang " + query.text("lang") + ", v " + query.text("v"));
    out.writeln(page.resolved(ParsedUrl("../api/ref").parts()).string());
    out.writeln(page.resolved(ParsedUrl("/").parts()).string());
    0;
}

module bible/xml v1.0.0;

// Reading a feed by element and attribute name, then writing a document
// from nodes: the tree is a value, and xml() is its text.
import "xml/parse" take ParsedXml;
import "xml/node" take XmlDocument, XmlElement, XmlText, XmlAttribute;
import "xml/name" take XmlName;
import "io/stdout" take Stdout;

main() is int {
    let out = Stdout();
    let feed = ParsedXml("<feed version=\"2\"><item><title>Tea &amp; milk</title></item>" +
        "<item><title>Bread</title></item></feed>").document().root();
    out.writeln("version " + feed.attribute("version"));
    for feed.children("item") -> item {
        out.writeln("- " + item.text("title"));
    }
    let note = XmlElement(XmlName("note"), [XmlAttribute(XmlName("lang"), "en")], [XmlText("1 < 2")]);
    out.writeln(XmlDocument(note).xml());
    0;
}

module bible/zones v1.0.0;

// Time zones from the bundled IANA database, never from the host: one call
// placed in Kostanay and read in three other cities, a wall time that a
// clock change skips, and the database version the answers depend on.
import "io/stdout" take Stdout;
import "time/zone" take Zone, ZonedDateTime, MissingLocalTime, TimeZoneDatabaseVersion;
import "time/iso" take IsoText;

main() is int {
    let out = Stdout();
    let home = Zone("Asia/Qostanay");
    let call = home.instant(IsoText("2026-12-01T19:00:00").local_date_time());
    out.writeln("the call, UTC:    " + call.string());
    for ["America/New_York", "Europe/Berlin", "Asia/Tokyo"] -> name {
        let there = ZonedDateTime(instant: call, zone: Zone(name));
        out.writeln(name + ": " + there.local_datetime().string() + " " + there.abbreviation());
    }
    let skipped = try {
        Zone("America/New_York").instant(IsoText("2026-03-08T02:30:00").local_date_time()).string();
    }
    catch e is MissingLocalTime {
        "2026-03-08 02:30 in New York: " + e.text();
    };
    out.writeln(skipped);
    out.writeln("tzdata " + TimeZoneDatabaseVersion().string());
    0;
}

module bible/filter v1.0.0;

import "io/stdout" take Stdout;

// A filter decides one line at a time. It keeps what the end of the run
// needs (here the number of matches) and returns what to print now.
object Matcher {
    has needle is string;
    has fold is bool = false;
    has matched is int = 0;

    Matcher(:needle, :fold);

    hit(line is string) is bool {
        if fold { line.lower().contains(needle.lower()); } else { line.contains(needle); }
    }

    // The lines to print for this input line.
    shown(line is string) is @string {
        if self.hit(line) { [line]; } else { []; }
    }

    // The matcher after this line.
    after(line is string) is ^Matcher {
        ^matched = if self.hit(line) { matched + 1; } else { matched; };
    }

    // As grep: 0 when something matched, 1 when nothing did.
    status() is int {
        if matched > 0 { 0; } else { 1; }
    }
}

// The shell: in a real tool the lines come from `for Stdin() -> line`.
object Filter {
    has input is @string;

    Filter(:input);

    run(matcher is Matcher) is int {
        let out = Stdout();
        let current = matcher;
        for input -> line {
            for current.shown(line) -> printed { out.writeln(printed); }
            current = current.after(line);
        }
        current.status();
    }
}

main() is int {
    let filter = Filter(input: ["Error: disk full", "ok", "error: retry", "ok"]);
    let first = filter.run(Matcher(needle: "error"));
    Stdout().writeln("status " + first.string());
    let second = filter.run(Matcher(needle: "error", fold: true));
    Stdout().writeln("status " + second.string());
    let third = filter.run(Matcher(needle: "panic"));
    Stdout().writeln("status " + third.string());
    0;
}

module bible/tally_output v1.0.0;

import "io/stdout" take Stdout;
import "os/environment" take Environment;
import "terminal/capability" take DetectedTerminalCapabilities, ColorPolicy, TerminalColorDepth;
import "terminal/style" take TextStyle, StyledText, DefaultColor, TextAttribute;
import "json" take Json, JsonField;

// What the tool found, rendered for people or for programs.
object Report {
    has lines is int;
    has words is int;
    has top is @string;

    Report(:lines, :words, :top);

    text(depth is TerminalColorDepth) is @string {
        let bold = TextStyle(foreground: DefaultColor(), background: DefaultColor(), attributes: [TextAttribute.bold]);
        let header = lines.string() + " lines, " + words.string() + " words";
        [StyledText(origin: header, style: bold).rendered(depth)] + top;
    }

    json() is string {
        let words_json = top.map() -> word { Json(word); };
        Json(JsonField("lines", lines), JsonField("words", words), JsonField("top", Json(items: words_json))).string();
    }
}

// Colours are decided once, from the facts a real run reads: whether the
// output is a terminal, the environment (NO_COLOR, TERM) and a policy.
object Display {
    has depth is TerminalColorDepth;

    Display(terminal is bool, environment is Environment) {
        let detected = DetectedTerminalCapabilities(
            input: false,
            output: terminal,
            native_depth: TerminalColorDepth.basic,
            columns: 80,
            rows: 24,
            environment: environment,
            policy: ColorPolicy.automatic,
        );
        depth = detected.capabilities()::Support::colors;
    }

    depth() is TerminalColorDepth { depth; }

    named() is string {
        match depth {
            case TerminalColorDepth.disabled { "no colour"; }
            case TerminalColorDepth.basic { "8 colours"; }
            case TerminalColorDepth.indexed { "256 colours"; }
            case TerminalColorDepth.true_color { "true colour"; }
        };
    }
}

main() is int {
    let out = Stdout();
    let report = Report(lines: 2, words: 12, top: ["the", "on"]);
    let piped = Display(terminal: false, environment: Environment(values: [:]));
    let muted = Display(terminal: true, environment: Environment(values: ["NO_COLOR": "1"]));
    let shown = Display(terminal: true, environment: Environment(values: ["TERM": "xterm"]));
    for [piped, muted, shown] -> display {
        let first = report.text(display.depth()).first().replace("\u{1b}", "ESC");
        out.writeln(display.named() + ": " + first);
    }
    out.writeln(report.json());
    0;
}

module bible/tidy v1.0.0;

import "io/stdout" take Stdout;
import "fs/path" take Path;
import "fs/file" take File, FileMode;
import "fs/entry" take FileEntry;
import "fs/directory" take Directory;
import "fs/temp" take TemporaryDirectory;

// What tidying one file would do: a value, decided before anything is written.
object Change {
    has path is Path;
    has before is @string;
    has after is @string;

    Change(:path, :before, :after);

    // How many lines differ.
    edits() is int {
        (0..before.size()).filter() -> index { before[index] != after[index]; }.size();
    }

    path() is Path { path; }
    after() is @string { after; }
}

object Tidy {
    Tidy();

    // The decision: trailing spaces removed from every line.
    planned(path is Path) is Change {
        let file = File(path: path);
        defer file.close();
        let before = file.text().lines();
        Change(path: path, before: before, after: before.map() -> line { line.trim_end(); });
    }

    // Doing it safely: write a sibling file, then move it over the original
    // in one step. A failure before the move leaves the original whole.
    applied(change is Change) is void {
        let sibling = Path(change.path().string() + ".tidy");
        let file = File(path: sibling, mode: FileMode.writing);
        for change.after() -> line { file.text().writeln(line); }
        file.close();
        FileEntry(sibling).move(destination: change.path(), overwrite: true);
    }
}

main() is int {
    let out = Stdout();
    let scratch = TemporaryDirectory(parent: Directory(Path(".")), prefix: "tidy-");
    defer scratch.close();
    let notes = scratch.path().child("notes.txt");
    let seed = File(path: notes, mode: FileMode.writing);
    seed.text().writeln("buy milk   ");
    seed.text().writeln("call Ada");
    seed.text().writeln("fix the gate  ");
    seed.close();

    let tidy = Tidy();
    let change = tidy.planned(notes);
    out.writeln("--dry-run: would change " + change.edits().string() + " of 3 lines");
    tidy.applied(change);
    out.writeln("after: " + tidy.planned(notes).edits().string() + " lines to change");
    0;
}

module bible/tally_settings v1.0.0;

import "io/stdout" take Stdout;
import "os/environment" take Environment;
import "cli/command" take CliCommand, Option;

// The order of precedence: a flag, then the environment, then the default.
// The environment is a value given to the object, never read behind its back.
object TopSetting {
    has command is CliCommand;
    has environment is Environment;

    TopSetting(:environment) {
        command = CliCommand(name: "tally", options: [Option(name: "top", short: "n", value: "N")]);
    }

    top(arguments is @string) is int {
        let call = command.invocation(arguments);
        call.int("top") else (environment.maybe("TALLY_TOP").int() else 3);
    }
}

main() is int {
    let out = Stdout();
    let plain = TopSetting(environment: Environment(values: [:]));
    let configured = TopSetting(environment: Environment(values: ["TALLY_TOP": "10"]));
    out.writeln("default: " + plain.top([]).string());
    out.writeln("environment: " + configured.top([]).string());
    out.writeln("flag: " + configured.top(["-n", "2"]).string());
    0;
}

module bible/tally_commands v1.0.0;

import "io/stdout" take Stdout;
import "cli/command" take CliCommand, Option, Flag, CliFailure;

// Two subcommands under one root. Each declares only what it takes.
object Commands {
    has count is CliCommand;
    has top is CliCommand;
    has root is CliCommand;

    Commands() {
        let counting = CliCommand(name: "count", summary: "Count lines and words");
        let ranking = CliCommand(
            name: "top",
            summary: "List the most frequent words",
            options: [Option(name: "n", value: "N", help: "How many words")],
        );
        count = counting;
        top = ranking;
        root = CliCommand(
            name: "tally",
            flags: [Flag(name: "help", short: "h", help: "Show this help")],
            commands: [counting, ranking],
        );
    }

    // What the arguments select, as text the example can print.
    selected(arguments is @string) is string {
        try {
            let call = root.invocation(arguments);
            if call.command() == top {
                "top, n = " + (call.int("n") else 3).string();
            } else if call.command() == count {
                "count";
            } else {
                "root only, path " + call.path().join(" ");
            }
        }
        catch e is CliFailure {
            "refused: " + e.text();
        };
    }
}

main() is int {
    let commands = Commands();
    let out = Stdout();
    out.writeln(commands.selected(["count"]));
    out.writeln(commands.selected(["top", "--n", "5"]));
    out.writeln(commands.selected(["top"]));
    out.writeln(commands.selected([]));
    out.writeln(commands.selected(["sort"]));
    0;
}

module bible/tally_tests v1.0.0;

